/* Shared chart and component presentation. Data and demo workflows remain in app.js. */
let visualId=0, mixView='donut', columnView='columns';
const chartId=prefix=>prefix+'-'+(++visualId);
const tipAttrs=text=>`tabindex="0" data-tip="${escapeHTML(text)}" aria-label="${escapeHTML(text)}"`;
const chartKey=(label,color)=>`<span><i style="--c:${color}"></i>${label}</span>`;
const chartEmpty=()=>'<div class="chart-empty"><span>◌</span><strong>No matching data</strong><p>Choose another source or sector to explore this view.</p></div>';
function shareMeter(value,color=colors[0]){return `<span class="share-cell"><span class="share-track"><span style="width:${Math.max(0,Math.min(100,value))}%;--c:${color}"></span></span><b>${fmt(value)}%</b></span>`}

flow=function(){
 const leftData=bySource().filter(r=>r.value>0),rightData=bySector().filter(r=>r.value>0),sum=total();if(!sum)return chartEmpty();
 let ly=52,ry=52;const left=leftData.map(s=>{const h=s.value/sum*230,r={...s,i:sources.indexOf(s.name),y:ly,h};ly+=h+12;return r}),right=rightData.map(s=>{const h=s.value/sum*230,r={...s,j:sectors.indexOf(s.name),y:ry,h};ry+=h+12;return r});
 const id=chartId('flow'),lo={},ro={},ribbons=[];
 left.forEach(l=>right.forEach(r=>{const value=matrix[l.i][r.j]*yf(year());if(!value)return;const h=value/sum*230,a=l.y+(lo[l.i]||0),b=r.y+(ro[r.j]||0);lo[l.i]=(lo[l.i]||0)+h;ro[r.j]=(ro[r.j]||0)+h;const label=`${l.name} → ${r.name} · ${energy(value)} ${unit()} · ${fmt(value/sum*100)}% of selected consumption`;ribbons.push(`<path class="flow-ribbon" d="M167 ${a} C285 ${a} 388 ${b} 505 ${b} L505 ${b+h} C388 ${b+h} 285 ${a+h} 167 ${a+h}Z" fill="url(#${id}-${l.i})" ${tipAttrs(label)} data-detail="${escapeHTML(label)}"><title>${escapeHTML(label)}</title></path>`)}));
 return `<div class="flow-summary"><span><i class="pulse-dot"></i>Energy flow explorer</span><b>${energy(sum)} <small>${unit()} total</small></b></div><svg class="energy-flow" viewBox="0 0 700 365" role="img" aria-label="Energy flow from source to final consumption"><defs>${left.map(l=>`<linearGradient id="${id}-${l.i}" x1="0" x2="1"><stop stop-color="${colors[l.i]}" stop-opacity=".68"/><stop offset="1" stop-color="${colors[l.i]}" stop-opacity=".25"/></linearGradient>`).join('')}</defs><text class="chart-overline" x="2" y="22">ENERGY SOURCES</text><text class="chart-overline" x="534" y="22">CONSUMPTION SECTORS</text>${ribbons.join('')}${left.map(l=>`<g class="flow-node" ${tipAttrs(`${l.name} · ${energy(l.value)} ${unit()}`)}><rect x="155" y="${l.y}" width="12" height="${l.h}" rx="4" fill="${colors[l.i]}"/><circle cx="7" cy="${l.y+l.h/2-6}" r="3.2" fill="${colors[l.i]}"/><text class="node-label" x="20" y="${l.y+l.h/2-2}">${l.name}</text><text class="node-value" x="20" y="${l.y+l.h/2+15}">${energy(l.value)} <tspan>${unit()}</tspan></text></g>`).join('')}${right.map((r,i)=>`<g class="flow-node" ${tipAttrs(`${r.name} · ${energy(r.value)} ${unit()}`)}><rect x="505" y="${r.y}" width="12" height="${r.h}" rx="4" fill="${['#2c715b','#59967c','#87b19a','#aec8b2'][i%4]}"/><text class="node-label" x="534" y="${r.y+r.h/2-2}">${r.name}</text><text class="node-value" x="534" y="${r.y+r.h/2+15}">${energy(r.value)} <tspan>${unit()}</tspan></text></g>`).join('')}<text class="chart-caption" x="350" y="351" text-anchor="middle">Hover or focus a flow to inspect its contribution</text></svg>`;
};

mix=function(){
 const a=bySource(),sum=total();let start=0;
 const arcs=a.filter(r=>r.value>0).map(r=>{let pct=r.value/sum*100,offset=start;start+=pct;let c=colors[sources.indexOf(r.name)],label=`${r.name} · ${energy(r.value)} ${unit()} · ${fmt(pct)}%`;
  if(mixView==='donut')return `<circle class="mix-segment" cx="110" cy="110" r="82" pathLength="100" fill="none" stroke="${c}" stroke-width="25" stroke-dasharray="${Math.max(.01,pct-(pct===100?0:.9))} ${100-Math.max(.01,pct-(pct===100?0:.9))}" stroke-dashoffset="${-offset}" transform="rotate(-90 110 110)" ${tipAttrs(label)}><title>${label}</title></circle>`;
  if(pct===100)return `<circle class="pie-segment" cx="110" cy="110" r="88" fill="${c}" ${tipAttrs(label)}/>`;
  const rad=p=>2*Math.PI*p/100-Math.PI/2,px=p=>110+88*Math.cos(rad(p)),py=p=>110+88*Math.sin(rad(p));return `<path class="pie-segment" d="M110 110 L${px(offset)} ${py(offset)} A88 88 0 ${pct>50?1:0} 1 ${px(offset+pct)} ${py(offset+pct)} Z" fill="${c}" stroke="white" stroke-width="3" ${tipAttrs(label)}><title>${label}</title></path>`;
 }).join('');
 return `<div class="chart-toolbar"><span class="chart-overline-html">FUEL COMPOSITION</span><div class="segmented" aria-label="Energy mix chart type"><button data-mix-view="donut" class="${mixView==='donut'?'selected':''}" aria-pressed="${mixView==='donut'}">Doughnut</button><button data-mix-view="pie" class="${mixView==='pie'?'selected':''}" aria-pressed="${mixView==='pie'}">Pie</button></div></div><div class="mix-body refined"><div class="mix-visual"><svg class="mix-svg" viewBox="0 0 220 220" role="img" aria-label="${mixView==='pie'?'Pie':'Doughnut'} chart of energy source shares"><circle cx="110" cy="110" r="82" fill="none" stroke="#f0f4ee" stroke-width="25"/>${arcs}${mixView==='donut'?`<text class="mix-total" x="110" y="108" text-anchor="middle">${energy(sum)}</text><text class="mix-total-label" x="110" y="129" text-anchor="middle">TOTAL ${unit()}</text>`:''}</svg>${mixView==='pie'?`<div class="pie-total">${energy(sum)} <span>${unit()} total</span></div>`:''}</div><div class="mix-legend">${a.map(r=>{const pct=sum?r.value/sum*100:0,c=colors[sources.indexOf(r.name)];return `<div class="mix-row" ${tipAttrs(`${r.name}: ${energy(r.value)} ${unit()}`)}><div class="mix-row-top"><span><i class="dot" style="--c:${c}"></i>${r.name}</span><b>${fmt(pct,0)}<small>%</small></b></div><div class="mix-share-track"><span style="width:${pct}%;background:${c}"></span></div></div>`}).join('')}</div></div>`;
};

bars=function(rows=bySector(),options={}){
 const max=Math.max(...rows.map(r=>r.value),1),display=options.display||((v)=>`${energy(v)} ${unit()}`);
 return `<div class="sector-bars refined-bars">${rows.map((r,i)=>`<div class="bar-row" ${tipAttrs(`${r.name} · ${display(r.value)}`)}><div class="bar-label"><span><i class="dot" style="--c:${colors[i%5]}"></i>${r.name}</span><b>${display(r.value)}</b></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,r.value/max*100)}%;--c:${colors[i%5]}"><span class="bar-end"></span></div></div></div>`).join('')}</div>`;
};

function columnChart(rows,currentLabel=year(),previousLabel=compare,display=v=>energy(v),u=unit()){
 if(!rows.length)return chartEmpty();const vals=rows.flatMap(r=>[r.value,r.value/yf(year())*yf(compare)]),max=Math.max(...vals,1)*1.22,W=660,H=300,L=52,R=18,T=30,B=68,baseline=H-B,step=(W-L-R)/rows.length,bw=Math.min(29,step*.25);const y=v=>baseline-v/max*(baseline-T);return `<svg class="column-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Grouped bar chart comparing ${currentLabel} and ${previousLabel}">${[0,1,2,3].map(i=>{const v=max*i/3;return `<line class="chart-grid" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text class="axis-tick" text-anchor="end" x="${L-10}" y="${y(v)+4}">${display(v)}</text>`}).join('')}${rows.map((r,i)=>{const x=L+step*i+step/2,p=r.value/yf(year())*yf(compare),current=`${r.name} · ${currentLabel}: ${display(r.value)} ${u}`,prior=`${r.name} · ${previousLabel}: ${display(p)} ${u}`;return `<g class="column-group"><rect class="comparison-bar" x="${x-bw-3}" y="${y(p)}" width="${bw}" height="${Math.max(0,baseline-y(p))}" rx="5" fill="#dbe7d4" ${tipAttrs(prior)}/><rect class="current-bar" x="${x+3}" y="${y(r.value)}" width="${bw}" height="${Math.max(0,baseline-y(r.value))}" rx="5" fill="${colors[i%5]}" ${tipAttrs(current)}/><text class="column-value" x="${x+3+bw/2}" y="${y(r.value)-9}" text-anchor="middle">${display(r.value)}</text><text class="column-label" text-anchor="middle" x="${x}" y="${baseline+21}">${r.name.length>18?r.name.slice(0,16)+'…':r.name}</text></g>`}).join('')}<text class="chart-caption" x="${L}" y="291">${u} · Illustrative annual values</text></svg><div class="chart-keys">${chartKey(currentLabel,'#4f916c')}${chartKey(previousLabel,'#dbe7d4')}</div>`;
}

trend=function(){
 const data=[2020,2021,2022,2023,2024].map(y=>({year:y,value:total(String(y))})),projected=data[4].value+(data[4].value-data[0].value)/4, max=Math.max(...data.map(r=>r.value),forecast?projected:0,1)*1.2,id=chartId('trend'),base=185,y=v=>base-v/max*145,pts=data.map((r,i)=>({x:55+i*105,y:y(r.value),...r}));let path=`M${pts[0].x} ${pts[0].y}`;pts.slice(1).forEach((p,i)=>{let prev=pts[i];path+=` C${prev.x+42} ${prev.y} ${p.x-42} ${p.y} ${p.x} ${p.y}`});return `<div class="trend-summary"><span class="chart-keys">${chartKey('Final consumption','#478568')}${forecast?chartKey('Projection','#e7a455'):''}</span><span class="tag">${unit()} · Annual</span></div><svg class="area-chart" viewBox="0 0 575 235" role="img" aria-label="Annual energy consumption trend, 2020 to 2024${forecast?', with 2025 projection':''}"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#82b993" stop-opacity=".32"/><stop offset="1" stop-color="#82b993" stop-opacity=".015"/></linearGradient></defs>${[0,1,2,3].map(i=>{let v=max*i/3;return `<line class="chart-grid" x1="55" x2="555" y1="${y(v)}" y2="${y(v)}"/><text class="axis-tick" x="43" y="${y(v)+4}" text-anchor="end">${energy(v)}</text>`}).join('')}<path d="${path} L475 ${base} L55 ${base}Z" fill="url(#${id})"/><path class="trend-line" d="${path}" fill="none" stroke="#478568" stroke-width="3"/>${pts.map(p=>`<g class="trend-point" ${tipAttrs(`${p.year} · ${energy(p.value)} ${unit()}`)}><rect x="${p.x-18}" y="20" width="36" height="${base-10}" fill="transparent"/><line class="hover-guide" x1="${p.x}" x2="${p.x}" y1="25" y2="${base}"/><circle class="point-halo" cx="${p.x}" cy="${p.y}" r="9" fill="#478568" fill-opacity=".12"/><circle cx="${p.x}" cy="${p.y}" r="4" fill="white" stroke="#478568" stroke-width="2.5"/><text class="axis-tick" x="${p.x}" y="210" text-anchor="middle">${p.year}</text></g>`).join('')}${forecast?`<path d="M475 ${pts[4].y} L550 ${y(projected)}" fill="none" stroke="#e7a455" stroke-width="2.5" stroke-dasharray="5 5"/><circle cx="550" cy="${y(projected)}" r="4" fill="white" stroke="#e7a455" stroke-width="2" ${tipAttrs(`2025 projection · ${energy(projected)} ${unit()} · Illustrative linear model`)}/><text class="axis-tick" x="550" y="210" text-anchor="middle">2025*</text>`:''}<text class="chart-caption" x="55" y="232">${forecast?'* Projection uses the slope between the 2020 and 2024 sample values.':'Synthetic observations · hover or focus a point to inspect a year'}</text></svg>`;
};

dataTable=function(rows=bySource(),label='Energy source'){
 const sorted=[...rows].sort((a,b)=>ascending?a.value-b.value:b.value-a.value),sum=rows.reduce((s,r)=>s+r.value,0);
 return `<div class="table-toolbar"><span class="table-count">${rows.length} <span>categories</span></span><div class="table-toggle"><label class="switch-label"><input id="share-toggle" type="checkbox" ${showShare?'checked':''}><span class="toggle-switch"></span>Share column</label><button class="table-sort" id="sort">${ascending?'↑':'↓'} Consumption</button></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">${label}</th><th scope="col" class="numeric">${year()} <span class="th-unit">${unit()}</span></th><th scope="col" class="numeric">${compare} <span class="th-unit">${unit()}</span></th>${showShare?'<th scope="col">Share of total</th>':''}<th scope="col">Data status</th></tr></thead><tbody>${sorted.map(r=>{const color=colors[Math.max(0,sources.indexOf(r.name))%5];return `<tr><td><span class="source-cell"><i class="source-token" style="--c:${color}">${r.name.slice(0,1)}</i><span>${r.name}</span></span></td><td class="numeric primary-value">${energy(r.value)}</td><td class="numeric muted-value">${energy(r.value/yf(year())*yf(compare))}</td>${showShare?`<td>${shareMeter(sum?r.value/sum*100:0,color)}</td>`:''}<td><span class="status">Illustrative</span></td></tr>`}).join('')||`<tr><td colspan="${showShare?5:4}">No matching records</td></tr>`}</tbody><tfoot><tr><td>Total consumption</td><td class="numeric">${energy(sum)}</td><td class="numeric">${energy(sum/yf(year())*yf(compare))}</td>${showShare?`<td>${sum?'100':'0'}%</td>`:''}<td><span class="table-count">${year()}</span></td></tr></tfoot></table></div><div class="table-caption"><span><i class="pulse-dot"></i>Filtered demonstration dataset</span><span>${rows.length} of ${rows.length} categories</span></div>`;
};

modulePage=function(){
 const c=moduleConfig[page],mult=moduleTab===1?.4:moduleTab===2?.75:1,rows=c.items.map((name,i)=>({name,value:c.values[i]*yf(year())*mult})).filter(r=>!selectedCategories.size||selectedCategories.has(r.name)),u=page==='electricity'?(moduleTab===1?'MW':'GWh'):unit(),disp=v=>fmt(v*(page==='electricity'?1:factor()));
 return `<div class="notice">Concept view · ${c.names[moduleTab]}. Values are synthetic. ${page==='electricity'?'Generation uses GWh; capacity uses illustrative MW. Load and sales are sample series.':'Energy totals convert with the selected unit.'}</div><div class="module-tabs full" role="tablist">${c.names.map((n,i)=>`<button role="tab" aria-selected="${moduleTab===i}" data-tab="${i}" class="${moduleTab===i?'selected':''}">${n}</button>`).join('')}</div><div class="grid"><section class="card">${title(c.names[moduleTab],`${year()} · ${u}`,`<div class="segmented"><button data-column-view="columns" class="${columnView==='columns'?'selected':''}">Columns</button><button data-column-view="bars" class="${columnView==='bars'?'selected':''}">Bars</button></div>`)}<div class="category-chips">${c.items.map(n=>`<label><input type="checkbox" data-cat="${n}" ${selectedCategories.has(n)||!selectedCategories.size?'checked':''}><span>${n}</span></label>`).join('')}</div>${columnView==='columns'?columnChart(rows,year(),compare,disp,u):bars(rows,{display:v=>disp(v)+' '+u})}${foot()}</section><section class="card">${title('Historical comparison','Category totals across selected annual periods')}<div class="period-compare">Compare with ${compareSelect()}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Category</th><th class="numeric">${year()} <span class="th-unit">${u}</span></th><th class="numeric">${compare} <span class="th-unit">${u}</span></th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><span class="table-source-dot" style="--c:${colors[i%5]}"></span>${r.name}</td><td class="numeric primary-value">${disp(r.value)}</td><td class="numeric muted-value">${disp(r.value/yf(year())*yf(compare))}</td></tr>`).join('')}</tbody></table></div><div class="table-caption"><span>Synthetic annual series</span><span>${rows.length} categories</span></div>${foot()}</section></div>`;
};

buildings=function(){
 const rows=buildingRows.filter(r=>isic==='All building types'||r[0]===isic);return `<div class="notice">ISIC building energy concept · Indicative classification mapping and synthetic benchmarks require confirmation with SLSEA.</div><div class="period-compare"><label for="isic">Building type</label><select id="isic"><option>All building types</option>${buildingRows.map(r=>`<option ${isic===r[0]?'selected':''}>${r[0]}</option>`).join('')}</select></div><div class="metrics">${metric('Total building energy',energy(rows.reduce((s,r)=>s+r[2],0)*yf(year())),unit())}${metric('Electricity EUI',fmt(rows.reduce((s,r)=>s+r[3],0)/rows.length,0),'kWh/m²/yr','Unweighted mean · demonstration')}${metric('Buildings represented',fmt(rows.length*48,0),'buildings','Synthetic building sample')}${metric('Reporting coverage','86','%','Illustrative reporting coverage')}</div><div class="grid"><section class="card">${title('Building energy composition',`Fuel mix by ISIC building type · ${year()} · ${unit()}`)}<div class="stacked-chart">${rows.map(r=>`<div class="stacked-row"><div class="bar-label"><span>${r[0]}</span><b>${energy(r[2]*yf(year()))}<small> ${unit()}</small></b></div><div class="stacked-track"><div class="stacked-group" style="width:${r[2]/12*100}%">${[.5,.2,.15,.1,.05].map((v,i)=>`<div class="stacked-segment" style="width:${v*100}%;background:${colors[i]}" ${tipAttrs(`${r[0]} · ${sources[i]}: ${energy(r[2]*yf(year())*v)} ${unit()} (${v*100}%)`)}>${v>=.15?`<span>${v*100}%</span>`:''}</div>`).join('')}</div></div></div>`).join('')}</div>${legend()}${foot()}</section><section class="card">${title('Energy use intensity','Electricity per gross floor area · kWh/m²/year')}${bars(rows.map(r=>({name:r[0],value:r[3]})),{display:v=>fmt(v,0)+' kWh/m²/yr'})}<div class="insight">EUI = annual electricity consumption (kWh) ÷ gross floor area (m²). Compare buildings with similar use, climate and occupancy.</div></section></div><section class="card">${title('Building energy register','Illustrative sector aggregates')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Building type</th><th>ISIC code</th><th class="numeric">Consumption <span class="th-unit">${unit()}</span></th><th class="numeric">EUI <span class="th-unit">kWh/m²/yr</span></th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><span class="source-cell"><i class="source-token" style="--c:${colors[i%5]}">${r[0][0]}</i>${r[0]}</span></td><td><span class="code-chip">${r[1]}</span></td><td class="numeric primary-value">${energy(r[2]*yf(year()))}</td><td class="numeric">${r[3]}</td></tr>`).join('')}</tbody></table></div></section>`;
};

const componentBaseRender=render,componentBaseModal=modal;
function upgradeComponents(){
 $$('table').forEach(t=>{t.classList.add('data-table');if(!t.parentElement.classList.contains('table-wrap')){const wrap=document.createElement('div');wrap.className='table-wrap';t.before(wrap);wrap.append(t)}t.querySelectorAll('td').forEach(td=>{if(/^\s*[\d,.]+(?:\s*%)?\s*$/.test(td.textContent))td.classList.add('numeric')})});
 $$('[data-mix-view]').forEach(b=>b.onclick=()=>{mixView=b.dataset.mixView;render()});
 $$('[data-column-view]').forEach(b=>b.onclick=()=>{columnView=b.dataset.columnView;render()});
 $$('[data-detail]').forEach(el=>{const show=()=>modal('Energy flow detail',`<div class="flow-detail"><span class="detail-icon">↗</span><h3>${escapeHTML(el.dataset.detail)}</h3><p>Selected period: ${year()} · Unit: ${unit()}<br>Source: synthetic demonstration data.<br>Hover, focus or select another flow to explore its contribution.</p></div>`);el.onclick=show;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}}});
 $$('[data-tip]').forEach(el=>{const show=e=>{let t=$('#chart-tooltip');if(!t){t=document.createElement('div');t.id='chart-tooltip';t.role='tooltip';document.body.append(t)}t.textContent=el.dataset.tip;t.style.display='block';const rect=el.getBoundingClientRect(),x=e.clientX||rect.left+rect.width/2,y=e.clientY||rect.top;t.style.left=Math.max(12,Math.min(x-110,window.innerWidth-255))+'px';t.style.top=Math.max(12,Math.min(y-55,window.innerHeight-65))+'px'};const hide=()=>{const t=$('#chart-tooltip');if(t)t.style.display='none'};el.onpointermove=show;el.onfocus=show;el.onpointerleave=hide;el.onblur=hide;el.addEventListener('click',hide)});
}
render=function(){const tip=$('#chart-tooltip');if(tip)tip.style.display='none';componentBaseRender();upgradeComponents()};
modal=function(t,html){componentBaseModal(t,html);upgradeComponents()};
render();
